#include <pthread.h>
#include <stdio.h>
#define CAP 2
struct q{int a[CAP];int h,t,n,closed;pthread_mutex_t m;pthread_cond_t ne,nf;};static struct q q={{0},0,0,0,0,PTHREAD_MUTEX_INITIALIZER,PTHREAD_COND_INITIALIZER,PTHREAD_COND_INITIALIZER};static int pop(int*out){pthread_mutex_lock(&q.m);while(q.n==0&&!q.closed)pthread_cond_wait(&q.ne,&q.m);if(q.n==0&&q.closed){pthread_mutex_unlock(&q.m);return 1;}*out=q.a[q.h];q.h=(q.h+1)%CAP;q.n--;pthread_cond_signal(&q.nf);pthread_mutex_unlock(&q.m);return 0;}static void *consumer(void*p){(void)p;int v,sum=0;while(pop(&v)==0)sum+=v;return (void*)(long)sum;}int main(void){pthread_t t;pthread_create(&t,0,consumer,0);for(int v=1;v<=3;v++){pthread_mutex_lock(&q.m);while(q.n==CAP&&!q.closed)pthread_cond_wait(&q.nf,&q.m);q.a[q.t]=v;q.t=(q.t+1)%CAP;q.n++;pthread_cond_signal(&q.ne);pthread_mutex_unlock(&q.m);}pthread_mutex_lock(&q.m);q.closed=1;pthread_cond_broadcast(&q.ne);pthread_cond_broadcast(&q.nf);pthread_mutex_unlock(&q.m);void*r=0;pthread_join(t,&r);pthread_cond_destroy(&q.ne);pthread_cond_destroy(&q.nf);pthread_mutex_destroy(&q.m);printf("sum=%ld\n",(long)r);return (long)r==6?0:1;}
